import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as a,a as s}from"./chunks/M-BT-BK.DTMS2NtJ.js";import{_ as n}from"./chunks/BDM.scaBLLhv.js";import{_ as r,o as l,c as d,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const B=JSON.parse('{"title":"Bridge Libre","description":"","frontmatter":{"source_hash":"dc2943a1ef","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/install/libreBT.md","filePath":"it/install/libreBT.md"}'),c={name:"it/install/libreBT.md"};function m(u,t,g,b,h,v){return l(),d("div",null,[...t[0]||(t[0]=[p('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   Libre Bluetooth</p></div><p>Sul mercato sono disponibili molti bridge da NFC a Bluetooth per i sensori Libre.</p><p>Il progetto originale è stato sviluppato da Joern: <a href="https://github.com/JoernL/LimiTTer" target="_blank" rel="noreferrer">LimiTTer</a>. Ricorda questo nome, perché compare come nome predefinito del bridge quando il dispositivo effettivo non viene identificato. A meno che tu non abbia davvero un LimiTTer (o non colleghi direttamente un Libre 2), vedere questo nome significa che il tuo bridge non è collegato a xDrip.</p><p>xDrip ne supporta alcuni, per alcuni sensori.<br><strong>Libre H e Libre 2/2+ USA/CA/AUS non sono supportati.</strong><br> Puoi usare Diabox o Juggluco in modalità <a href="./libre2patch.html">Libre patched app</a>.</p><p>Qui sotto trovi una tabella di compatibilità dei bridge supportati; per i sensori compatibili è indicata la versione <strong>minima</strong> del firmware.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Bridge</th><th style="text-align:center;">- Libre 1 / Pro -</th><th style="text-align:center;">- 14 giorni USA -</th><th style="text-align:center;">- Libre 2/2+ UE -</th></tr></thead><tbody><tr><td style="text-align:center;">MiaoMiao</td><td style="text-align:center;"><code>Sì</code></td><td style="text-align:center;"><code>39*</code></td><td style="text-align:center;"><code>39*</code></td></tr><tr><td style="text-align:center;">MiaoMiao 2</td><td style="text-align:center;"><code>Sì</code></td><td style="text-align:center;"><code>7*</code></td><td style="text-align:center;"><code>7*</code></td></tr><tr><td style="text-align:center;">MiaoMiao 3</td><td style="text-align:center;"><code>Sì</code></td><td style="text-align:center;"><code>3A*</code></td><td style="text-align:center;"><code>3A*</code></td></tr><tr><td style="text-align:center;">Atom</td><td style="text-align:center;"><code>Sì</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><p><em>Nota:</em><br><em><code>*</code> <a href="./../use/OOP.html">richiede l&#39;add-on esterno OOP</a></em></p><br><h2 id="bridge-settings" tabindex="-1">Impostazioni del bridge <a class="header-anchor" href="#bridge-settings" aria-label="Permalink to &quot;Impostazioni del bridge {#bridge-settings}&quot;">​</a></h2><p>Se non l&#39;hai ancora fatto, <a href="./install.html#make-sure-xdrip-will-not-be-put-to-sleep">verifica che xDrip non venga messo in sospensione</a>.</p><p>Prima di provare a collegare il bridge, verifica che le impostazioni siano corrette, per evitare disconnessioni frequenti.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  Impostazioni Meno Usate<br>   Impostazioni Bluetooth</p></div><p>Per iniziare, usa le impostazioni indicate qui sotto.</p><p>Il Bluetooth deve essere acceso. <strong>Attiva</strong> <code>Attiva Bluetooth</code>.</p><div class="admonition xdripitem"><p class="admonition-title">Attiva Bluetooth <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Attiva automaticamente il bluetooth se è spento quando si prova a connettersi a un dispositivo bluetooth</p></div><p><strong>Attiva</strong> il Watchdog, ma leggi le informazioni qui sotto.</p><div class="admonition xdripitem"><p class="admonition-title">Watchdog Bluetooth <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Resetta Bluetooth (spegni e riaccendi) se non si ricevono dati in 20 minuti</p></div><div class="info custom-block"><p class="custom-block-title">Informazioni</p><p>Tieni presente che Watchdog Bluetooth spegne e riaccende il Bluetooth del telefono: questo provoca una disconnessione Bluetooth temporanea di tutti i dispositivi collegati. Potresti voler disattivare questa funzione se usi AAPS e il tuo bridge/microinfusore non recupera automaticamente la connessione Bluetooth.</p></div><p><strong>Disattiva</strong> la chiusura GATT.</p><div class="admonition xdripitem"><p class="admonition-title">Chiusura GATT per scollegamento BLE <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Se il watchdog bluetooth si attiva spesso, provare a deselezionare questa opzione per vedere se aiuta</p></div><p>Se il bridge perde la connessione e una scansione Bluetooth ti permette di recuperarla, puoi provare ad attivare <code>Usa scansione</code>. Per iniziare lasciala <strong>disattivata</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Usa scansione <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Scansiona prima di connettersi a xBridge e Libre Bluetooth</p></div><p>Sui telefoni Samsung e su molti telefoni cinesi <strong>devi disattivare <code>Trust Auto-Connect</code></strong>! Se il telefono perde la connessione, <strong>disattivala</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Trust Auto-Connect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Usa e confida nella funzione di connessione automatica bluetooth di Android (sconsigliato per miaomiao)</p></div><p>Con Android 8 e successivi puoi attivare <code>Usa Scansione In Background</code>. Se perdi la connessione, <strong>lasciala disattivata</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Usa Scansione In Background <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utilizza la funzione di scansione bluetooth in background Android 8+</p></div><p>Lascia <strong>disattivate</strong> entrambe le opzioni qui sotto.</p><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Wakelocks <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Vecchi wakelocks bluetooth (possono necessitare più batteria) che potrebbero essere necessari per la ricezione dei bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">Resetta costantemente bluetooth <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Resetta Bluetooth spegnendolo e riaccendendolo ogni pochi minuti! Selezionare solo per prove. Potrebbe disturbare qualsiasi altra cosa usando bluetooth.</p></div><p>Se il tuo bridge è un Transmitter_T o un Droplet, attiva questa opzione; altrimenti lasciala <strong>disattivata</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Supporto Transmiter (PL) <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Supporto sperimentale per Transmiter_T</p></div><p>Se hai perdite di connessione puoi <strong>attivare</strong> la modalità di polling. Non farà nulla di utile, se non tenere sveglio il Bluetooth del telefono.</p><div class="admonition xdripitem"><p class="admonition-title">xBridge+ Modalità di Polling <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Supporto sperimentale per la funzione di polling xBridge+</p></div><p>Se il tuo bridge è un vecchio BluCon compatibile puoi attivare questa opzione; se ricevi più richieste di abbinamento al giorno, lasciala <strong>disattivata</strong>.<br><em>Nota: solo il BluCon si abbina ad Android, gli altri bridge no.</em></p><div class="admonition xdripitem"><p class="admonition-title">Consenti unbonding Blucon <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Adatto solo per telefoni che supportano l&#39;accoppiamento automatico</p></div><br><p>Riavvia il telefono per assicurarti che tutti i parametri vengano presi in considerazione.</p><br><h2 id="connect-bluetooth-bridge" tabindex="-1">Collegare il bridge Bluetooth <a class="header-anchor" href="#connect-bluetooth-bridge" aria-label="Permalink to &quot;Collegare il bridge Bluetooth {#connect-bluetooth-bridge}&quot;">​</a></h2><p>Assicurati che il bridge non sia collegato a nient&#39;altro: nessun altro dispositivo e nessun&#39;altra app.<br> Avvia la scansione Bluetooth.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Scansione Bluetooth</p></div><p>Se la scansione non parte da sola, seleziona <code>SCANSIONE</code>.</p><img src="'+a+'" style="zoom:75%;"><p>Se il bridge non compare, assicurati che sia completamente carico (o che abbia una batteria nuova) e resettalo.</p><p>Quando è visibile, selezionalo.</p><p>Se il tuo bridge è un Blucon, inserisci il codice scritto sul lato.</p><img src="'+s+'" style="zoom:55%;"><p>Posizionalo correttamente sul sensore. Alcuni bridge hanno una tolleranza molto ridotta riguardo all&#39;angolo e alla distanza dal sensore.</p><div class="info custom-block"><p class="custom-block-title">Add-on esterno</p><p>Se il tuo sensore richiede un <a href="./../use/OOP.html">algoritmo OOP (out of process algorithm)</a>, assicurati di installarlo adesso.</p></div><br><p>Prosegui con <a href="./../use/startsensor.html#libre">Inizializza Sensore</a></p><h2 id="stop-libre-sensor" tabindex="-1">Fermare il sensore Libre <a class="header-anchor" href="#stop-libre-sensor" aria-label="Permalink to &quot;Fermare il sensore Libre {#stop-libre-sensor}&quot;">​</a></h2><p>xDrip non può fermare fisicamente un sensore Libre: si fermerà da solo dopo 14 giorni e 12 ore e continuerà a mostrare l&#39;ultimo valore.</p><p>Tuttavia, quando cambi sensore è fortemente consigliato informare xDrip del cambio fermando il sensore.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Stop Sensore</p></div><p>Conferma che vuoi davvero fermare il sensore.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;"> Arresto Sensore <span class="symbol"></span></p><p> Ferma il tuo sensore solo quando pensi di rimuoverlo, altrimenti lascialo avviato!</p><p>       <span style="background-color:white;color:black;"> STOP SENSORE </span></p></div><p>Questo azzererà tutte le calibrazioni e permetterà a xDrip di avviare un nuovo sensore.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',60)])])}const A=r(c,[["render",m]]);export{B as __pageData,A as default};
